  border-top:0 !important; box-shadow:none !important;
  backdrop-filter:none !important; -webkit-backdrop-filter:none !important;
}
.chat-detail-screen .input-area-custom::before,
.chat-detail-screen .input-area-custom::after{ content:none !important; }
.chat-detail-screen .input-area-custom *{ border-top-color:transparent !important; }
.chat-detail-screen .input-row-wrapper{ align-items:center !important; gap:8px !important; border:0 !important; }

.chat-detail-screen .input-area-custom .input-btn-plus{
  position:relative !important; flex:0 0 auto !important;
  width:auto !important; min-width:56px !important; height:30px !important;
  padding:0 !important; margin:0 !important;
  border:0 !important; border-radius:0 !important;
  background:transparent !important; background-image:none !important;
  box-shadow:none !important; color:transparent !important;
}
