}

.msg-system::before,
[class*="msg-recall"]::before,
[class*="system-msg"]::before,
.msg-revoke::before {
  content: "叮咚 您有一條新的訊息通知被撤回已阻止៷>ᴗ<៷" !important;
  font-size: 11px !important;
  color: var(--system-msg-color) !important;
  opacity: 0.75 !important;
  font-weight: 400 !important;
  letter-spacing: 0.3px !important;
  display: inline-block !important;
}

.msg-system a,
.msg-system button,
[class*="msg-recall"] a,
[class*="msg-recall"] button,
[class*="reedit"] {
  font-size: 11px !important;
  color: #3b82f6 !important;
  text-decoration: none !important;
  margin-left: 6px !important;
  font-weight: 500 !important;
  cursor: pointer !important;
}

/* ============================================================
   13. 通话卡片与心声安全间距修复
   ============================================================ */

[class*="call"],
[class*="voip"],
.msg-call-card,
.msg-bubble-wrapper:has([class*="call"]),
.msg-bubble-wrapper:has([class*="voip"]) {
  margin-top: 8px !important;
  margin-bottom: 8px !important;
  clear: both !important;
  position: relative !important;
  z-index: 1 !important;
}

.msg-narration-custom,
[class*="thought"],
[class*="mind"],
.msg-bubble-wrapper:has([class*="thought"]),
.msg-bubble-wrapper:has([class*="mind"]) {
  margin-top: 10px !important;
  margin-bottom: 10px !important;
  clear: both !important;
  position: relative !important;
  z-index: 2 !important;
}

/* ============================================================
   14. 图片与表情包尺寸约束
   ============================================================ */

.msg-image-wrapper,
.msg-image-wrapper img {
  max-width: 220px !important;
  max-height: 280px !important;
  border-radius: 10px !important;
  object-fit: cover !important;
  overflow: hidden !important;
  display: block !important;
}

.chat-messages-area img:not(.msg-avatar-custom),
.bubble-me-custom img,
.bubble-them-custom img,
.msg-plain-me img,
.msg-plain-them img {
  max-width: 90px !important;
  max-height: 190px !important;
  height: auto !important;
  border-radius: 8px !important;
}

.bubble-me-custom:has(.msg-image-wrapper),
.bubble-them-custom:has(.msg-image-wrapper),
.bubble-me-custom:has(img:not(.msg-avatar-custom)),
.bubble-them-custom:has(img:not(.msg-avatar-custom)) {
  padding: 0 !important;
  background: transparent !important;
}
